import 'dart:async';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter/foundation.dart';
import 'package:flutter_soloud/flutter_soloud.dart';

import 'audio_analyzer.dart';
import 'audio_frame.dart';

enum PlaybackState { idle, loading, playing, paused, stopped, error }

/// Playback and analysis are isolated from UI/rendering.
/// Visualization events are generated by SoLoud from the real mixer output.
class AudioEngine extends ChangeNotifier {
  final SoLoud _soloud = SoLoud.instance;
  final AudioAnalyzer _analyzer = AudioAnalyzer();

  StreamSubscription<AudioVisualizationData>? _visualizationSub;
  AudioSource? _source;
  SoundHandle? _handle;

  PlaybackState state = PlaybackState.idle;
  AudioFrame frame = AudioFrame.silence();
  final ValueNotifier<AudioFrame> frameListenable = ValueNotifier(AudioFrame.silence());
  String trackName = 'No track selected';
  String? trackPath;
  Duration position = Duration.zero;
  Duration duration = Duration.zero;
  String? errorMessage;
  bool _initialized = false;
  Future<void>? _initializing;

  SoundHandle? get currentHandle => _handle;
  bool get sourceLoaded => _source != null;

  void updatePosition(Duration value) {
    position = value > duration && duration > Duration.zero ? duration : value;
    if (state == PlaybackState.playing &&
        duration > Duration.zero &&
        position >= duration) {
      state = PlaybackState.stopped;
      _handle = null;
      frame = AudioFrame.silence();
      frameListenable.value = frame;
    }
    notifyListeners();
  }

  Future<void> initialize() async {
    if (_initialized) return;
    final pending = _initializing;
    if (pending != null) return pending;
    final task = () async {
      await _soloud.init();
      _soloud.setVisualizationEnabled(
        true,
        windowSize: 1024,
        kind: VisualizationKind.waveAndFft,
        channel: VisualizationChannel.merged,
      );
      _soloud.setFftSmoothing(0.72);
      _visualizationSub = _soloud.audioVisualizationEvents.listen(_onVisualization);
      _initialized = true;
    }();
    _initializing = task;
    try {
      await task;
    } finally {
      _initializing = null;
    }
  }

  void setSmoothing(double value) {
    _analyzer.smoothing = value.clamp(0.05, 0.95);
  }

  void _onVisualization(AudioVisualizationData packet) {
    if (state != PlaybackState.playing) return;
    final fft = packet.fftData ?? Float32List(0);
    final wave = packet.waveData ?? Float32List(0);
    frame = _analyzer.analyze(fft: fft, wave: wave, position: position);
    frameListenable.value = frame;
  }


  Future<void> loadFile(String path) async {
    await initialize();
    state = PlaybackState.loading;
    errorMessage = null;
    notifyListeners();
    try {
      if (_handle != null) {
        await _soloud.stop(_handle!);
        _handle = null;
      }
      if (_source != null) {
        await _soloud.disposeSource(_source!);
        _source = null;
      }
      final file = File(path);
      _source = await _soloud.loadFile(file.path);
      trackPath = path;
      trackName = path.split(Platform.pathSeparator).last;
      position = Duration.zero;
      duration = _soloud.getLength(_source!);
      state = PlaybackState.paused;
      frame = AudioFrame.silence();
      frameListenable.value = frame;
    } catch (e) {
      state = PlaybackState.error;
      errorMessage = e.toString();
      frame = AudioFrame.silence();
      frameListenable.value = frame;
    }
    notifyListeners();
  }

  Future<void> play() async {
    if (_source == null) return;
    if (state == PlaybackState.paused && _handle != null) {
      _soloud.setPause(_handle!, false);
    } else {
      _handle = await _soloud.play(_source!);
    }
    state = PlaybackState.playing;
    notifyListeners();
  }

  Future<void> pause() async {
    if (_handle == null || state != PlaybackState.playing) return;
    _soloud.setPause(_handle!, true);
    state = PlaybackState.paused;
    notifyListeners();
  }

  Future<void> stop() async {
    if (_handle != null) {
      await _soloud.stop(_handle!);
      _handle = null;
    }
    position = Duration.zero;
    frame = AudioFrame.silence();
    frameListenable.value = frame;
    state = _source == null ? PlaybackState.idle : PlaybackState.stopped;
    notifyListeners();
  }

  Future<void> seek(Duration value) async {
    if (_handle == null || duration == Duration.zero) return;
    final clamped = value < Duration.zero
        ? Duration.zero
        : (value > duration ? duration : value);
    _soloud.seek(_handle!, clamped);
    position = clamped;
    notifyListeners();
  }

  @override
  void dispose() {
    _visualizationSub?.cancel();
    if (_handle != null) _soloud.stop(_handle!);
    if (_source != null) _soloud.disposeSource(_source!);
    if (_initialized) _soloud.deinit();
    frameListenable.dispose();
    super.dispose();
  }
}
